**React** is a JavaScript library for building user interfaces, created by Facebook. It uses a component-based architecture and a virtual DOM for efficient updates.

```jsx
// Functional Component with Hooks (Modern React)
import React, { useState } from 'react';

// Child component receiving props
function Greeting({ name, onGreet }) {
    return (
        <div>
            <h2>Hello, {name}!</h2>
            <button onClick={() => onGreet(name)}>Say Hi</button>
        </div>
    );
}

// Parent component with state
function CounterApp() {
    // useState hook for state management
    const [count, setCount] = useState(0);
    const [name, setName] = useState('');

    // Event handler
    const handleIncrement = () => {
        setCount(count + 1);
    };

    const handleDecrement = () => {
        setCount(count - 1);
    };

    const handleGreet = (personName) => {
        alert(`Hi ${personName}! Count is ${count}`);
    };

    return (
        <div style={{ padding: '20px', fontFamily: 'Arial' }}>
            <h1>React Counter Demo</h1>

            <input 
                type="text"
                placeholder="Enter your name"
                value={name}
                onChange={(e) => setName(e.target.value)}
            />

            <div>
                <h2>Count: {count}</h2>
                <button onClick={handleIncrement}>+1</button>
                <button onClick={handleDecrement}>-1</button>
                <button onClick={() => setCount(0)}>Reset</button>
            </div>

            {name && <Greeting name={name} onGreet={handleGreet} />}
        </div>
    );
}

export default CounterApp;
```

