**Conditional Rendering:**

```jsx
function ConditionalRender({ isLoggedIn, items }) {
    // If-else
    if (isLoggedIn === null) return <div>Loading...</div>;

    // Ternary
    return (
        <div>
            {isLoggedIn ? (
                <div>
                    <h1>Welcome back!</h1>
                    {items.length === 0 ? (
                        <p>No items</p>
                    ) : (
                        <ul>{items.map(item => <li key={item.id}>{item.name}</li>)}</ul>
                    )}
                </div>
            ) : (
                <button>Login</button>
            )}

            {/* Logical AND */}
            {isLoggedIn && <button>Logout</button>}
        </div>
    );
}
```

