**Vue Composition API (Modern Approach):**

```vue
<script setup>
import { ref, computed, onMounted, watch } from 'vue';

// Props definition
const props = defineProps({
  initialTitle: { type: String, default: 'My Todo List' }
});

// Reactive state with ref
const title = ref(props.initialTitle);
const newTodo = ref('');
const todos = ref([]);
const currentFilter = ref('all');
const nextId = ref(1);

// Computed properties
const totalCount = computed(() => todos.value.length);
const completedCount = computed(() => todos.value.filter(t => t.completed).length);
const remainingCount = computed(() => totalCount.value - completedCount.value);

const filteredTodos = computed(() => {
  if (currentFilter.value === 'active') {
    return todos.value.filter(t => !t.completed);
  }
  if (currentFilter.value === 'completed') {
    return todos.value.filter(t => t.completed);
  }
  return todos.value;
});

// Methods
function addTodo() {
  if (newTodo.value.trim()) {
    todos.value.push({
      id: nextId.value++,
      text: newTodo.value,
      completed: false
    });
    newTodo.value = '';
  }
}

function deleteTodo(id) {
  todos.value = todos.value.filter(todo => todo.id !== id);
}

// Lifecycle
onMounted(() => {
  const saved = localStorage.getItem('vue-todos');
  if (saved) {
    todos.value = JSON.parse(saved);
    nextId.value = todos.value.length + 1;
  }
});

// Watch
watch(todos, (newTodos) => {
  localStorage.setItem('vue-todos', JSON.stringify(newTodos));
}, { deep: true });

// Emit events to parent
const emit = defineEmits(['update', 'delete']);
</script>
```

