**Angular** is a TypeScript-based framework developed by Google for building enterprise-scale web applications. It provides a complete solution with dependency injection, routing, forms, and HTTP client built-in.

```typescript
// app.component.ts - Angular Component
import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnInit {
  // Properties
  title = 'My Angular Todo App';
  newTodoText = '';
  todos: Todo[] = [];
  currentFilter: 'all' | 'active' | 'completed' = 'all';
  nextId = 1;

  // Dependency Injection (example)
  constructor(private todoService: TodoService) {}

  // Lifecycle hook - runs after component initialization
  ngOnInit(): void {
    this.loadTodos();
  }

  // Methods
  addTodo(): void {
    if (this.newTodoText.trim()) {
      const newTodo: Todo = {
        id: this.nextId++,
        text: this.newTodoText,
        completed: false
      };
      this.todos.push(newTodo);
      this.newTodoText = '';
      this.saveTodos();
    }
  }

  deleteTodo(id: number): void {
    this.todos = this.todos.filter(todo => todo.id !== id);
    this.saveTodos();
  }

  toggleTodo(id: number): void {
    const todo = this.todos.find(t => t.id === id);
    if (todo) {
      todo.completed = !todo.completed;
      this.saveTodos();
    }
  }

  get filteredTodos(): Todo[] {
    if (this.currentFilter === 'active') {
      return this.todos.filter(t => !t.completed);
    }
    if (this.currentFilter === 'completed') {
      return this.todos.filter(t => t.completed);
    }
    return this.todos;
  }

  get totalCount(): number {
    return this.todos.length;
  }

  get completedCount(): number {
    return this.todos.filter(t => t.completed).length;
  }

  get remainingCount(): number {
    return this.totalCount - this.completedCount;
  }

  private loadTodos(): void {
    const saved = localStorage.getItem('angular-todos');
    if (saved) {
      this.todos = JSON.parse(saved);
      this.nextId = Math.max(...this.todos.map(t => t.id), 0) + 1;
    }
  }

  private saveTodos(): void {
    localStorage.setItem('angular-todos', JSON.stringify(this.todos));
  }

  setFilter(filter: 'all' | 'active' | 'completed'): void {
    this.currentFilter = filter;
  }
}
```

