**Angular Service with Dependency Injection:**

```typescript
// todo.service.ts
import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { map, catchError } from 'rxjs/operators';

export interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

@Injectable({
  providedIn: 'root'  // Singleton service available everywhere
})
export class TodoService {
  private storageKey = 'angular-todos';

  constructor(private http: HttpClient) {}

  getTodos(): Observable<Todo[]> {
    // Try localStorage first
    const saved = localStorage.getItem(this.storageKey);
    if (saved) {
      return of(JSON.parse(saved));
    }

    // Fallback to API
    return this.http.get<Todo[]>('/api/todos')
      .pipe(
        map(todos => {
          this.saveTodos(todos);
          return todos;
        }),
        catchError(error => {
          console.error('Error loading todos:', error);
          return of([]);
        })
      );
  }

  saveTodos(todos: Todo[]): void {
    localStorage.setItem(this.storageKey, JSON.stringify(todos));
  }

  addTodo(todo: Todo): Observable<Todo> {
    return this.http.post<Todo>('/api/todos', todo);
  }

  updateTodo(todo: Todo): Observable<Todo> {
    return this.http.put<Todo>(`/api/todos/${todo.id}`, todo);
  }

  deleteTodo(id: number): Observable<void> {
    return this.http.delete<void>(`/api/todos/${id}`);
  }
}
```

